<div class="meta-page"><header class="meta-page-header"><div><h1>Plantillas de Meta</h1><p>Consulta y valida las plantillas reales de WhatsApp Business.</p></div><button type="button" class="primary-btn" wire:click="syncMetaTemplates" wire:loading.attr="disabled"><span wire:loading.remove wire:target="syncMetaTemplates">↻ Consultar Meta</span><span wire:loading wire:target="syncMetaTemplates">Consultando…</span></button></header><section class="card meta-card">@if($metaError)<div class="meta-error" role="alert">{{ $metaError }}</div>@elseif(!$metaLoaded)<p class="meta-empty">Presiona “Consultar Meta” para cargar las plantillas de la cuenta configurada.</p>@elseif(count($metaTemplates) === 0)<p class="meta-empty">Meta no devolvió plantillas para esta cuenta.</p>@else<div class="meta-table-wrap"><table class="meta-table"><thead><tr><th>Nombre</th><th>Idioma</th><th>Categoría</th><th>Estado</th><th>Validación local</th></tr></thead><tbody>@foreach($metaTemplates as $template)<tr><td><strong>{{ $template['name'] }}</strong><small>{{ $template['id'] }}</small></td><td>{{ $template['language'] ?: '—' }}</td><td>{{ $template['category'] ?: '—' }}</td><td><span class="meta-status meta-status-{{ strtolower($template['status']) }}">{{ $template['status'] }}</span></td><td>@if($this->localTemplateExists($template['name']))<span class="meta-match">✓ Coincide</span>@else<span class="meta-no-match">No existe localmente</span>@endif</td></tr>@endforeach</tbody></table></div>@endif</section><style>.meta-page{max-width:1200px}.meta-page-header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:20px}.meta-page-header h1{margin:0;color:#14263f;font-size:30px}.meta-page-header p{margin:7px 0 0;color:#384b63;font-size:14px}.meta-card{padding:22px}.meta-empty{color:#64748b;font-size:14px}.meta-error{padding:12px;border:1px solid #fecaca;border-radius:8px;background:#fef2f2;color:#b91c1c}.meta-table-wrap{overflow-x:auto}.meta-table{width:100%;border-collapse:collapse;font-size:13px}.meta-table th,.meta-table td{padding:12px 10px;border-top:1px solid #e2e8f0;text-align:left}.meta-table th{color:#64748b;font-size:11px;text-transform:uppercase}.meta-table small{display:block;margin-top:3px;color:#94a3b8;font-size:10px}.meta-status,.meta-match,.meta-no-match{display:inline-block;padding:4px 8px;border-radius:999px;font-size:11px;font-weight:700}.meta-status-approved,.meta-status-active,.meta-match{background:#dcfce7;color:#166534}.meta-status-pending,.meta-status-in_review{background:#fef3c7;color:#92400e}.meta-status-rejected,.meta-status-paused,.meta-status-disabled{background:#fee2e2;color:#991b1b}.meta-status-unknown,.meta-no-match{background:#f1f5f9;color:#475569}@media(max-width:600px){.meta-page-header{align-items:flex-start;flex-direction:column}}</style></div>
